/** Сайт оборачивает числа в невидимые метки направления (U+2066…U+2069): «⁦3 / 4⁩». */
export const BIDI = '[\\u2066-\\u2069]?';

export const SUBMIT_RPC = '/rest/v1/rpc/submit_writing_attempt';
export const DRAFT_RPC = '/rest/v1/rpc/save_writing_draft';

/** Подписи «רמת כתיבה להתחלה» (форма профиля, #be58fd; Figma A5 178-2154). */
export const WRITING_LEVEL_LABELS: Record<1 | 2 | 3 | 4, string> = {
  1: 'עקיבה וזיהוי צורת אות',
  2: 'אותיות ומילים קצרות',
  3: 'משפט קצר',
  4: 'כתיבה חופשית קצרה',
};

/** Задания письма уровня 1 со стилусом (#493b35). */
export const LEVEL1_TASKS = ['מִי בַּבַּיִת', 'חַיָּה אֲהוּבָה'] as const;

/** Первый видимый элемент локатора. */
export const vis = (l: Locator) => l.filter({ visible: true }).first();

/** Год рождения для возраста N лет. TODO verify: сайт считает возраст как «текущий год − год рождения» (форма просит только год). */
export const birthYearForAge = (age: number) => String(new Date().getFullYear() - age);

export interface NewChildOptions {
  birthYear: string;
  /** «רמת כתיבה להתחלה» 1–4; не задан — «בלי בחירה — לפי הגיל». */
  writingLevel?: 1 | 2 | 3 | 4;
  /** «רמת קריאה משוערת» 1–10 (#976cbc); не задан — старт по возрасту. */
  readingEstimate?: number;
}

/**
 * Создать профиль ребёнка на /children/new с уровнями из формы. Возвращает id ребёнка
 * (из ответа POST /rest/v1/children, запасной вариант — из адреса).
 */
export async function createChildWithLevels(page: Page, name: string, opts: NewChildOptions): Promise<string> {
  await page.goto('/children/new');
  await expect(vis(page.getByText('פרופיל ילד חדש'))).toBeVisible();
  await vis(page.getByLabel('שם או כינוי')).fill(name);
  await vis(page.getByLabel(/שנת לידה/)).fill(opts.birthYear); // TODO verify selector (label «שנת לידה»)

  if (opts.writingLevel) {
    // TODO verify selector: варианты «רמת כתיבה להתחלה» — role=radio с подписью уровня
    await vis(page.getByRole('radio', { name: new RegExp(WRITING_LEVEL_LABELS[opts.writingLevel]) })).click();
  }
  if (opts.readingEstimate !== undefined) {
    // TODO verify selector: тип поля «רמת קריאה משוערת» (выпадающий список / радио 1–10 / число) при записи не проверен.
    const n = String(opts.readingEstimate);
    // Радио ищем внутри группы «רמת קריאה משוערת», иначе «2» совпадёт с «רמה 2 · …» уровня письма.
    const radio = vis(
      page.getByRole('radiogroup', { name: /רמת קריאה משוערת/ }).getByRole('radio', { name: new RegExp(`(^|\\D)${n}(\\D|$)`) }),
    );
    const field = vis(page.getByLabel(/רמת קריאה משוערת/));
    const tag = await field.evaluate((el) => el.tagName.toLowerCase()).catch(() => '');
    if (tag === 'select') await field.selectOption(n);
    else if (tag === 'input' || tag === 'textarea') await field.fill(n);
    else await radio.click();
  }

  const created = page.waitForResponse((r) => r.request().method() === 'POST' && /\/rest\/v1\/children(\?|$)/.test(r.url()));
  await vis(page.getByRole('button', { name: /שמיר|שמור/ })).click(); // TODO verify selector (текст кнопки сохранения)
  const resp = await created;
  expect(resp.ok(), `создание профиля: HTTP ${resp.status()}`).toBeTruthy();

  let id: string | undefined;
  try {
    const body = await resp.json();
    id = Array.isArray(body) ? body[0]?.id : body?.id;
  } catch {
    /* тело может быть пустым (return=minimal) — берём id из адреса ниже */
  }
  if (!id) {
    await page.waitForURL(/\/children\/[0-9a-f-]{36}/);
    id = page.url().match(/\/children\/([0-9a-f-]{36})/)?.[1];
  }
  if (!id) throw new Error('Не удалось получить id созданного ребёнка (ни из ответа сервера, ни из адреса)');
  return id;
}

/** Передача устройства новому ребёнку → C1 → «אחר כך» → дом ребёнка (/<id>/home). */
export async function handoverToChildHome(page: Page, childId: string, childName: string) {
  await page.goto(`/children/${childId}/handover`);
  await vis(page.getByRole('button', { name: `${childName}, בואו נתחיל!` })).click();
  await page.waitForURL(new RegExp(`/${childId}/(assessment/intro|home)$`));
  if (/\/assessment\/intro$/.test(page.url())) {
    await readingScreens(page).later.click();
  }
  await page.waitForURL(childUrl(childId, 'home'));
}

/** Строка «כתיבה: N / 4» в профиле ребёнка у родителя (/children/<id>). */
export async function expectWritingLevelInProfile(page: Page, childId: string, level: number) {
  await page.goto(`/children/${childId}`);
  await expect(vis(page.getByText('רמות נוכחיות (להורה בלבד)'))).toBeVisible();
  await expect(vis(page.getByText(/כתיבה:/))).toHaveText(new RegExp(`כתיבה:.*${BIDI}${level} / 4${BIDI}`));
}

/** Локаторы полотна письма (D3, #0e3868) и отправки (#b39e08). */
export function writingSurface(page: Page) {
  const confirm = vis(page.getByRole('dialog').filter({ hasText: 'לשלוח לבנג׳י?' }));
  const processing = vis(page.getByRole('dialog').filter({ hasText: /בנג׳י קורא/ }));
  return {
    typingMode: vis(page.getByRole('radio', { name: /הקלדה/ })),
    handMode: vis(page.getByRole('radio', { name: /כתיבה ביד/ })),
    // TODO verify selector: поле печати (aria-label «אזור ההקלדה» по #493b35)
    typingField: vis(page.getByRole('textbox', { name: /אזור ההקלדה/ })),
    // Холст рукописи — единственный способ найти его без класса. TODO verify selector
    canvas: vis(page.locator('canvas')),
    saved: vis(page.getByText('נשמר', { exact: true })),
    finish: vis(page.getByRole('button', { name: 'לסיים תרגול', exact: true })),
    confirm,
    send: confirm.getByRole('button', { name: 'לשלוח', exact: true }),
    notYet: confirm.getByRole('button', { name: 'עוד לא', exact: true }),
    processing,
    // Отзыв (D6): кнопка «לתרגול הבא». TODO verify selector
    feedbackNext: vis(page.getByRole('button', { name: 'לתרגול הבא' })),
    errorCard: vis(page.getByText('אופס, הייתה אצלי תקלה')),
    offlineCard: vis(page.getByText('אין חיבור לאינטרנט')),
    retry: vis(page.getByRole('button', { name: 'ננסה שוב', exact: true })),
  };
}

/** Каталог «משימות כתיבה» ребёнка. */
export async function openWritingCatalog(page: Page, childId: string) {
  await page.goto(`/${childId}/writing/pick`);
  await expect(vis(page.getByText('משימות כתיבה'))).toBeVisible(); // TODO verify selector (заголовок каталога D2)
}

/**
 * Открыть задание из каталога: по названию или первое в списке. Каждое открытие — новый черновик (кейсы #b39e08).
 * TODO verify selector: карточка задания — кнопка с названием задания.
 */
export async function openWritingTask(page: Page, title?: string) {
  const card = title
    ? vis(page.getByRole('button', { name: new RegExp(title) }))
    : vis(page.getByRole('button').filter({ hasText: /דק׳|דקות|כתיבה ביד|קל|בינוני|מאתגר/ }));
  await card.click();
  await expect(writingSurface(page).finish).toBeVisible();
}

/** Перейти в «הקלדה», ввести текст и дождаться ответа save_writing_draft и «נשמר». */
export async function typeDraft(page: Page, text: string) {
  const s = writingSurface(page);
  if ((await s.typingMode.getAttribute('aria-checked')) !== 'true') await s.typingMode.click();
  await expect(s.typingField).toBeVisible();
  const saved = page.waitForResponse((r) => r.url().includes(DRAFT_RPC), { timeout: 30_000 });
  await s.typingField.fill(text);
  const resp = await saved;
  expect(resp.status(), `save_writing_draft: HTTP ${resp.status()}`).toBe(200);
  await expect(s.saved).toBeVisible({ timeout: 30_000 });
}

/** Нарисовать n штрихов мышью по холсту рукописи. */
export async function drawStrokes(page: Page, n = 3) {
  const s = writingSurface(page);
  await expect(s.canvas).toBeVisible();
  const box = await s.canvas.boundingBox();
  if (!box) throw new Error('У холста рукописи нет boundingBox');
  for (let i = 0; i < n; i++) {
    const y = box.y + box.height * (0.3 + 0.15 * i);
    await page.mouse.move(box.x + box.width * 0.3, y);
    await page.mouse.down();
    await page.mouse.move(box.x + box.width * 0.5, y + 10, { steps: 8 });
    await page.mouse.move(box.x + box.width * 0.7, y, { steps: 8 });
    await page.mouse.up();
  }
}

/** Фокус внутри элемента (окно подтверждения / обработки). */
export async function expectFocusInside(dialog: Locator, where: string) {
  await expect
    .poll(() => dialog.evaluate((el) => el.contains(document.activeElement)), { message: `${where}: фокус вышел из окна` })
    .toBe(true);
}

/** Учёт запросов submit_writing_attempt: число и id отправки (p_attempt_id / submission_key). */
export function trackSubmits(page: Page) {
  const requests: { at: number; key: string; req: Request }[] = [];
  page.on('request', (req) => {
    if (!req.url().includes(SUBMIT_RPC) || req.method() !== 'POST') return;
    let body: Record<string, unknown> = {};
    try {
      body = (req.postDataJSON() ?? {}) as Record<string, unknown>;
    } catch {
      /* не JSON */
    }
    // TODO verify: имена полей тела запроса (p_attempt_id / p_submission_key) по заметкам QA 02.11.
    const key = String(body.p_submission_key ?? body.submission_key ?? body.p_attempt_id ?? body.attempt_id ?? JSON.stringify(body));
    requests.push({ at: Date.now(), key, req });
  });
  return {
    requests,
    count: () => requests.length,
    keys: () => [...new Set(requests.map((r) => r.key))],
    reset: () => requests.splice(0, requests.length),
  };
}

/** Уникальный печатный текст для отправки (осмысленный иврит + метка QA-AUTO). */
export function qaWritingText(): string {
  const tag = Math.random().toString(36).slice(2, 8);
  return `QA-AUTO-${tag} הילד קורא ספר יפה בבית והוא שמח מאוד היום`;
}
